/* Wicked Skunk 52 by Javierrocadev — https://uiverse.io/Javierrocadev/wicked-skunk-52 */
.card {
  width: 350px;
  height: 160px;
  background: #f7f9f9;
  padding: 10px;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  align-items: flex-start;
}

.card__title {
  font-size: 1.4em;
  font-weight: 800;
}

.card__text {
  font-weight: 500;
}

.card__button {
  cursor: pointer;
  background-color: rgb(15, 20, 25);
  color: #f7f9f9;
  font-size: 1.15em;
  border: none;
  padding: 5px 15px;
  border-radius: 15px;
}

.card__button:hover {
  background-color: #272C30;
}
